 1	predicate sorted_between (a:array<int>, from:nat, to:nat)
 2	  reads a;
 3	  requires a != null;
 4	  requires from <= to;
 5	  requires to <= a.Length;
 6	{
 7	  forall i,j :: from <= i < j < to && 0 <= i < j < a.Length ==> a[i] <= a[j]
 8	}
 9	  
10	predicate sorted (a:array<int>)
11	  reads a;
12	  requires a!=null;
13	{
14	  sorted_between (a, 0, a.Length)
15	}
16	
17	method bubbleSort (a: array<int>)
18	  modifies a;
19	  requires a != null;
20	  requires a.Length > -1;
21	  ensures sorted(a);
22	  ensures multiset(old(a[..])) == multiset(a[..]);
23	{
24	  var i:nat := 1;
25	
26	  while (i < a.Length)
27	    invariant i <= a.Length;
28	    invariant sorted_between (a, 0, i);
29	    invariant multiset(old (a[..])) == multiset(a[..]);
30	  {
31	    var j:nat := i;
32	    while (j > 0)
33	      invariant 0 <= j <= i;
34	      invariant sorted_between (a, 0, j);
35	      invariant forall u,v:: 0 <= u < j < v < i+1 ==> a[u] <= a[v];
36	      invariant sorted_between (a, j, i+1);
37	      invariant multiset(old (a[..])) == multiset(a[..]);
38	    {
39	      if (a[j-1] > a[j]) {
40	        var temp:int := a[j-1];
41	        // Introduced bug for permutation
42	        a[j-1] := a[j];
43	        //a[j-1] := a[j-1];
44	        a[j] := temp;
45	      }
46	      j := j - 1;
47	    }
48	    i := i+1;
49	  }
50	}
51

